def seed_integrations(apps, schema_editor):
    """The three Integrations cards start like the install already behaves: WhatsApp sending is on, emails go
    from the platform address while the own domain waits for DNS, and no health app is linked."""
    Integration = apps.get_model("gym", "Integration")
    start = {
        "whatsapp": ("connected", {}),
        "email_domain": ("pending", {"domain": "trainwithvimal.com"}),
        "health": ("not_connected", {"types": {"steps": True, "sleep": True, "hr": False, "workouts": True}}),
    }
    for kind, (status, config) in start.items():
        row, made = Integration.objects.get_or_create(kind=kind, defaults={"status": status, "config": config})
        if not made and not row.connected_at and not row.config:  # a row the old list page made, never set up
            row.status, row.config = status, config
            row.save()


